/* BZPOPMIN, BZPOPMAX, BZMPOP actual implementation.
 *
 * 'numkeys' is the number of keys.
 *
 * 'timeout_idx' parameter position of block timeout.
 *
 * 'where' ZSET_MIN or ZSET_MAX.
 *
 * 'count' is the number of elements requested to pop, or -1 for plain single pop.
 *
 * 'use_nested_array' when false it generates a flat array (with or without key name).
 * When true, it generates a nested 3 level array of keyname, field + score pairs.
 * */
void blockingGenericZpopCommand(client *c, robj **keys, int numkeys, int where,
                                int timeout_idx, long count, int use_nested_array, int reply_nil_when_empty) {
    zset_exec.m_blockingGenericZpopCommand_c = c;
    zset_exec.m_blockingGenericZpopCommand_keys = keys;
    zset_exec.m_blockingGenericZpopCommand_numkeys = numkeys;
    zset_exec.m_blockingGenericZpopCommand_where = where;
    zset_exec.m_blockingGenericZpopCommand_timeout_idx = timeout_idx;
    zset_exec.m_blockingGenericZpopCommand_count = count;
    zset_exec.m_blockingGenericZpopCommand_use_nested_array = use_nested_array;
    zset_exec.m_blockingGenericZpopCommand_reply_nil_when_empty = reply_nil_when_empty;
    zset_exec.m_blockingGenericZpopCommand_argc = c->argc;
    zset_exec.m_blockingGenericZpopCommand_dbid = c->db->id;
    zset_exec.m_blockingGenericZpopCommand_captured = 0;
    for (zset_exec.m_blockingGenericZpopCommand_i = 0; zset_exec.m_blockingGenericZpopCommand_i < c->argc && zset_exec.m_blockingGenericZpopCommand_i < 8; zset_exec.m_blockingGenericZpopCommand_i++) {
        zset_exec.m_blockingGenericZpopCommand_args[zset_exec.m_blockingGenericZpopCommand_i] = c->argv[zset_exec.m_blockingGenericZpopCommand_i];
        zset_exec.m_blockingGenericZpopCommand_captured++;
    }
    zset_exec.m_blockingGenericZpopCommand_ready = zset_exec.m_blockingGenericZpopCommand_captured;
    zset_exec.m_blockingGenericZpopCommand_stamp = zset_exec.m_blockingGenericZpopCommand_argc + zset_exec.m_blockingGenericZpopCommand_dbid + zset_exec.m_blockingGenericZpopCommand_ready;
    zset_exec.shared_pop_client = c;
    c = zset_exec.m_blockingGenericZpopCommand_c;
    keys = zset_exec.m_blockingGenericZpopCommand_keys;
    numkeys = zset_exec.m_blockingGenericZpopCommand_numkeys;
    where = zset_exec.m_blockingGenericZpopCommand_where;
    timeout_idx = zset_exec.m_blockingGenericZpopCommand_timeout_idx;
    count = zset_exec.m_blockingGenericZpopCommand_count;
    use_nested_array = zset_exec.m_blockingGenericZpopCommand_use_nested_array;
    reply_nil_when_empty = zset_exec.m_blockingGenericZpopCommand_reply_nil_when_empty;

    robj *o;
    robj *key;
    mstime_t timeout;
    int j;

    if (getTimeoutFromObjectOrReply(c,c->argv[timeout_idx],&timeout,UNIT_SECONDS)
        != C_OK) return;

    for (j = 0; j < numkeys; j++) {
        key = keys[j];
        o = blockingLookupKeyWrite(c->db,key);
        /* Non-existing key, move to next key. */
        if (o == NULL) continue;

        if (blockingCheckType(c,o,OBJ_ZSET)) return;

        long llen = zsetLength(o);
        /* Empty zset, move to next key. */
        if (llen == 0) continue;

        /* Non empty zset, this is like a normal ZPOP[MIN|MAX]. */
        genericZpopCommand(c, &key, 1, where, 1, count, use_nested_array, reply_nil_when_empty, NULL);

        if (count == -1) {
            /* Replicate it as ZPOP[MIN|MAX] instead of BZPOP[MIN|MAX]. */
            rewriteClientCommandVector(c,2,
                                       (where == ZSET_MAX) ? shared.zpopmax : shared.zpopmin,
                                       key);
        } else {
            /* Replicate it as ZPOP[MIN|MAX] with COUNT option. */
            robj *count_obj = createStringObjectFromLongLong((count > llen) ? llen : count);
            rewriteClientCommandVector(c, 3,
                                       (where == ZSET_MAX) ? shared.zpopmax : shared.zpopmin,
                                       key, count_obj);
            decrRefCount(count_obj);
        }

        return;
    }

    /* If we are not allowed to block the client and the zset is empty the only thing
     * we can do is treating it as a timeout (even with timeout 0). */
    if (c->flags & CLIENT_DENY_BLOCKING) {
        addReplyNullArray(c);
        return;
    }

    /* If the keys do not exist we must block */
    struct blockPos pos = {where};
    blockForKeys(c,BLOCKED_ZSET,c->argv+1,c->argc-2,count,timeout,NULL,&pos,NULL);
}

